<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { usePortal } from '../portal'
import SubmissionEvidence from './SubmissionEvidence.vue'
import { achievements } from '../domain'
const portal=usePortal(),filter=ref<'pending'|'reviewed'>('pending'),selectedId=ref<number|null>(null)
const emit=defineEmits<{graded:[]}>()
const rows=computed(()=>filter.value==='pending'?portal.pending:portal.reviewed)
watch(rows,rows=>{if(!rows.some(r=>r.id===selectedId.value))selectedId.value=rows[0]?.id??null},{immediate:true})
const selected=computed(()=>portal.submissions.find(r=>r.id===selectedId.value)??null)
const snapshot=computed(()=>selected.value?portal.snapshot(selected.value.id):null)
const score=computed(()=>snapshot.value?achievements(snapshot.value.trials,snapshot.value.config,snapshot.value.transferId).reduce((n,r)=>n+r.earned,0):0)
const form=ref({reviewer:'',explanation:0,limits:0,feedback:'',trialIds:[] as number[]})
watch(selectedId,()=>{const r=selected.value?.reviews.at(-1);form.value={reviewer:r?.reviewer??'',explanation:r?.explanation??0,limits:r?.limits??0,feedback:r?.feedback??'',trialIds:r?[...r.trialIds]:[]}}, {immediate:true})
function grade(){if(selected.value&&portal.grade(selected.value.id,form.value)){filter.value='reviewed';emit('graded')}}
function exportReviews(){const url=URL.createObjectURL(new Blob([portal.exportJson()],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='本地提交与批阅快照.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template><main class="teacher-workspace"><aside class="teacher-inbox"><div class="core-eyebrow">教师端演示</div><h1>本地批阅列表</h1><p>这里只查看已提交快照，不读取学生未提交的草稿。</p><div class="teacher-filters"><button :class="{active:filter==='pending'}" @click="filter='pending'">待批阅 {{ portal.pending.length }}</button><button :class="{active:filter==='reviewed'}" @click="filter='reviewed'">已批阅 {{ portal.reviewed.length }}</button></div><p v-if="!rows.length" class="core-small">{{ filter==='pending'?'暂无待批阅版本。请先在学生端正式提交报告。':'暂无已批阅版本。' }}</p><button v-for="r in rows" :key="r.id" class="submission-row" :class="{active:r.id===selectedId}" @click="selectedId=r.id"><b>本地学习者 · 提交V{{ r.version }}</b><small>{{ new Date(r.submittedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}) }}</small><span>{{ r.origin }} · {{ r.reviews.length?'已批阅':'待批阅' }}</span></button><button class="btn" @click="exportReviews">导出提交与批阅备份</button><p class="core-small">不同版本分别批阅。当前为同一浏览器的本地角色演示，尚无班级账号与跨设备同步。</p></aside><section class="teacher-main"><div v-if="portal.error" class="core-warning">{{ portal.error }}</div><div v-if="portal.message" class="core-card" role="status">{{ portal.message }}</div><template v-if="selected&&snapshot"><div class="core-card"><div class="core-eyebrow">冻结的已提交版本 · {{ selected.origin }}</div><h1>提交V{{ selected.version }}的报告与证据</h1><p>学生草稿的后续修改不会改变此副本。自动证据 {{ score }}/70；论证评分由教师录入。</p><SubmissionEvidence :snapshot="snapshot" /></div><section class="core-card"><h2>批阅这个版本</h2><form @submit.prevent="grade"><label class="field"><span>复核教师</span><input v-model="form.reviewer" aria-label="复核教师" maxlength="20000" required /></label><div class="core-two"><label class="field"><span>解释与证据一致 /20</span><input v-model.number="form.explanation" aria-label="解释与证据评分" type="number" min="0" max="20" step="1" required /></label><label class="field"><span>结论边界 /10</span><input v-model.number="form.limits" aria-label="结论边界评分" type="number" min="0" max="10" step="1" required /></label></div><p>引用的完整仿真记录：</p><div class="core-compare-choices"><label v-for="t in snapshot.trials.filter(t=>t.complete)" :key="t.id"><input v-model="form.trialIds" type="checkbox" :value="t.id" />#{{ t.id }}</label></div><label class="field"><span>依据与改进反馈</span><textarea v-model="form.feedback" aria-label="教师反馈" rows="4" maxlength="20000" required /></label><button class="btn primary" type="submit">保存对本版本的批阅</button></form></section><section v-if="selected.reviews.length" class="core-card"><h2>本版本批阅历史</h2><article v-for="(r,i) in selected.reviews" :key="i"><h3>第{{ i+1 }}次 · {{ r.reviewer }}</h3><p>{{ new Date(r.at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}) }} · {{ r.explanation }}/20 + {{ r.limits }}/10 · 引用 {{ r.trialIds.join('、') }}</p><p class="evidence-text">{{ r.feedback }}</p></article></section></template><section v-else class="core-card"><h2>选择一个已提交版本开始批阅</h2><p>学生端完成正式提交后，会在本地列表中生成独立快照。未完成的草稿和操作演练不会出现在这里。</p></section></section></main></template>
